// src/app/actions/titles.ts
'use server';

import { revalidatePath } from 'next/cache';
import { z } from 'zod';

const createTitleSchema = z.object({
  title: z.string().min(3).max(255),
  description: z.string().min(10),
  periodId: z.number().int().positive(),
  quota: z.number().int().min(1),
});

type CreateTitleInput = z.infer<typeof createTitleSchema>;

export async function createTitle(formData: FormData) {
  const validated = createTitleSchema.safeParse({
    title: formData.get('title'),
    description: formData.get('description'),
    periodId: Number(formData.get('periodId')),
    quota: Number(formData.get('quota')),
  });

  if (!validated.success) {
    return { error: 'Invalid input', details: validated.error.flatten() };
  }

  const response = await fetch(`${process.env.API_URL}/api/titles`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify(validated.data),
  });

  if (!response.ok) {
    const error = await response.json();
    return { error: error.message || 'Failed to create title' };
  }

  revalidatePath('/admin/titles');
  return { success: true };
}
